export interface APIResponse<T> {
  success: boolean;
  data: T;
  message?: string;
  errors?: string[];
  timestamp: string;
}

export interface UploadResult {
  uploadId: string;
  fileName: string;
  totalRecords: number;
  errorRecords: number;
  clustersCreated: number;
  clustersUpdated: number;
  /** Test cases already available when the response is sent. */
  testCasesGenerated: number;
  /** Clusters whose test cases are still being generated by the AI in the background. */
  testCasesQueued: number;
  /** Occurrence records attached by a backfill (mode=backfill uploads). */
  occurrencesStored?: number;
  /** Non-fatal problems, e.g. AI not configured so rule-based bug titles were used. */
  warnings?: string[];
}

export interface PipelineStatus {
  /** Clusters waiting for / undergoing AI test-case generation. */
  pendingClusters: number;
  /** Clusters whose background test-case generation failed (retry via "Regenerate Test Cases"). */
  failedClusters: number;
  /** Most recent AI error, shortened. */
  lastError?: string;
}
